const float TIME_SCALE = 0.25;
const float TOTAL_DISTANCE_SCALE = 0.25;


// Colorpalette

vec3 palette( in float t )
{
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.0, 0.33, 0.66);
    return a + b*cos( 6.283185*(c*t+d) );
}

// Rotation matrix

mat2 rot2D(float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

// Operations

float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float opSubtraction( float d1, float d2 )
{
    return max(-d1,d2);
}

// Geometries

float sdSphere( vec3 p, float s )
{
  return length(p)-s;
}


float sdOctahedron( vec3 p, float s )
{
  p = abs(p);
  float m = p.x+p.y+p.z-s;
  vec3 q;
       if( 3.0*p.x < m ) q = p.xyz;
  else if( 3.0*p.y < m ) q = p.yzx;
  else if( 3.0*p.z < m ) q = p.zxy;
  else return m*0.57735027;

  float k = clamp(0.5*(q.z-q.y+s),0.0,s); 
  return length(vec3(q.x,q.y-s+k,q.z-k)); 
}

// Combined SDFs for raymarching

float sdfMap(vec3 point) {

    // infinite repetition by modulo
    float repetitionFactor = 1.0;
    //point.xy = mod(point.xy, repetitionFactor) - repetitionFactor / 2.0;
    // seperated z so we can animate it with time
    //point.z = mod(point.z + iTime * TIME_SCALE, repetitionFactor) - repetitionFactor / 2.0;

    // time animated rotate around y-axis so swizzle .xz
    point.xz *= rot2D(iTime);

    // scale so the geometry fits into repeated cells
    float scale = 0.5;
    float scaleToCell = scale * repetitionFactor;

    float sphere = sdSphere(point, scaleToCell * 0.4);
    float octahedron = sdOctahedron(point, scaleToCell * 0.5);

    // smooth union of both shapes
    float shape = opSmoothUnion(octahedron, sphere, 0.01);
    return shape;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates and fix stretched pixels (from -1 to 1)
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    // Camera and ray setup
    vec3 rayOrigin = vec3(0, 0, -3);
    vec3 rayDirection = normalize(vec3(uv, 1));

    // Raymarching until hit or length exceeded
    float totalDistance = 0.0;
    int i = 0;
    for (i = 0; i < 64; i++) {
        vec3 point = rayOrigin + rayDirection * totalDistance;

        float currentDistance = sdfMap(point);
        totalDistance += currentDistance;
        if (currentDistance < 0.001 || totalDistance > 100.0) break;
    }

    // get color based on distance
    //vec3 col = palette(totalDistance * TOTAL_DISTANCE_SCALE);

    // hack using final i value to make it less "flat"
    //vec3 col = palette(float(i) * 0.01 + TOTAL_DISTANCE_SCALE);

    // add time because we added it to point.z, making palette seem to be stationary
    //vec3 col = palette(float(i) * 0.01 + totalDistance * TOTAL_DISTANCE_SCALE + iTime * TIME_SCALE);

    // subtract time because we added it to point.z, making palette seem to propagate
    vec3 col = palette(float(i) * 0.01 + totalDistance * TOTAL_DISTANCE_SCALE - iTime * TIME_SCALE * 2.0); 

    // fade to black
    col -= totalDistance * 0.1;

    // output color, alphachannel ignored by shadertoy
    fragColor = vec4(totalDistance, 1.0);
}
